--   5. 4 个核心业务定时任务占位 (DEV_JOB, 初始状态 STOPPED, M3 启用)
-- =============================================================================

SET NAMES utf8mb4;

-- -----------------------------------------------------------------------------
-- 1. 学校组织根节点（承载原 orgs 中 parent_org_id=1 或 NULL 的学院节点）
-- -----------------------------------------------------------------------------
