  (`ID`, `PARENT_ID`, `DIRECTOR_ID`, `NAME`, `CODE`, `CATEGORY`, `SORT_CODE`, `EXT_JSON`, `DELETE_FLAG`, `CREATE_TIME`, `CREATE_USER`, `UPDATE_TIME`, `UPDATE_USER`)
VALUES
  ('1900100000000000000', '0', NULL, '学校总部', 'SCHOOL_ROOT', 'COMPANY', 1, '{"source":"warnsys_init"}', 'NOT_DELETE', NOW(), '1543837863788879871', NOW(), '1543837863788879871')
ON DUPLICATE KEY UPDATE
