-- -----------------------------------------------------------------------------
-- 4. 对齐 MinIO 文件存储引擎配置 (DEV_CONFIG)
-- -----------------------------------------------------------------------------
UPDATE `DEV_CONFIG` SET `CONFIG_VALUE` = 'MINIO' WHERE `CONFIG_KEY` = 'SNOWY_SYS_DEFAULT_FILE_ENGINE';
UPDATE `DEV_CONFIG` SET `CONFIG_VALUE` = 'minioadmin' WHERE `CONFIG_KEY` = 'SNOWY_FILE_MINIO_ACCESS_KEY';
UPDATE `DEV_CONFIG` SET `CONFIG_VALUE` = 'minioadmin123' WHERE `CONFIG_KEY` = 'SNOWY_FILE_MINIO_SECRET_KEY';
UPDATE `DEV_CONFIG` SET `CONFIG_VALUE` = 'http://127.0.0.1:9100' WHERE `CONFIG_KEY` = 'SNOWY_FILE_MINIO_END_POINT';
UPDATE `DEV_CONFIG` SET `CONFIG_VALUE` = 'warnsys-files' WHERE `CONFIG_KEY` = 'SNOWY_FILE_MINIO_DEFAULT_BUCKET_NAME';

